/** Bumped whenever a breaking change is made to any /v1 contract. */
export const API_CONTRACT_VERSION = '1.0.0-alpha.1' as const;

/** URL prefix for every versioned endpoint. */
export const API_BASE_PATH = '/v1' as const;

/**
 * Header used to correlate a single patient journey across kiosk, PWA, core API,
 * AI worker and HIS adapter. Required on every request; generated by the client.
 */
export const CORRELATION_ID_HEADER = 'x-correlation-id' as const;

/**
 * Header carrying the idempotency key for submissions and token requests.
 * Format for tokens: `<kioskId>-<preCheckinId>`.
 */
export const IDEMPOTENCY_KEY_HEADER = 'idempotency-key' as const;

